import {createServer} from 'node:http';
import {spawn,execFileSync} from 'node:child_process';
import {mkdirSync,writeFileSync,readFileSync,existsSync} from 'node:fs';
import {resolve} from 'node:path';
import {createInterface} from 'node:readline';
const base=resolve('reports/tool-capture/codex');const project=resolve(base,'project');const home=resolve(base,'home');
mkdirSync(project,{recursive:true});mkdirSync(home,{recursive:true});
execFileSync('git',['init','--quiet',project],{windowsHide:true});
const raw=resolve(base,'raw.jsonl');if(existsSync(raw))throw Error('capture exists');
const recorder=resolve(base,'record.mjs');
writeFileSync(recorder,`import {appendFileSync} from 'node:fs';let text='';for await(const c of process.stdin)text+=c;appendFileSync(process.argv[2],JSON.stringify(JSON.parse(text))+'\\n');\n`);
const command=`node "${recorder.replaceAll('\\','/')}" "${raw.replaceAll('\\','/')}"; exit $LASTEXITCODE`;
writeFileSync(resolve(home,'hooks.json'),JSON.stringify({hooks:{PreToolUse:[{hooks:[{type:'command',command,commandWindows:command}]}],PostToolUse:[{hooks:[{type:'command',command,commandWindows:command}]}]}},null,2));
let turns=0;
const server=createServer(async(req,res)=>{
 let body='';for await(const c of req)body+=c;
 if(!req.url.endsWith('/responses')){res.writeHead(404).end();return;}
 const value=JSON.parse(body);
 writeFileSync(resolve(base,'request-keys.json'),JSON.stringify(Object.keys(value)));
 const tool={type:'function',name:'exec_command'};
 const use=turns++===0;
 const input='*** Begin Patch\n*** Add File: capture.txt\n+Native tool fixture only.\n*** End Patch';
 const item=use?(tool.type==='custom'?{type:'custom_tool_call',id:'ctc_vouch_capture',call_id:'call_vouch_capture',name:tool.name,input}: {type:'function_call',id:'fc_vouch_capture',call_id:'call_vouch_capture',name:tool.name,arguments:JSON.stringify(tool.name==='apply_patch'?{input}:{cmd:'Write-Output "Native tool fixture only."',max_output_tokens:30})}):{type:'message',id:'msg_capture',role:'assistant',status:'completed',content:[{type:'output_text',text:'Native tool capture completed.',annotations:[]}]};
 const response={id:`resp_capture_${turns}`,object:'response',created_at:1790510000,status:'completed',model:value.model,output:[item],usage:{input_tokens:100,output_tokens:20,total_tokens:120}};
 res.writeHead(200,{'Content-Type':'text/event-stream'});
 const emit=(type,data)=>res.write(`event: ${type}\ndata: ${JSON.stringify({type,...data})}\n\n`);
 emit('response.created',{response:{...response,status:'in_progress',output:[]}});
 emit('response.output_item.added',{output_index:0,item});
 emit('response.output_item.done',{output_index:0,item});
 emit('response.completed',{response});res.end();
});
await new Promise(r=>server.listen(0,'127.0.0.1',r));
let config=`model_provider = "capture"\n[model_providers.capture]\nname = "Local fixed fixture provider"\nbase_url = "http://127.0.0.1:${server.address().port}/v1"\nwire_api = "responses"\nrequires_openai_auth = false\nrequest_max_retries = 0\nstream_max_retries = 0\n[analytics]\nenabled = false\n[features]\nhooks = true\nplugins = false\nremote_plugin = false\n[projects.${JSON.stringify(project)}]\ntrust_level = "trusted"\n`;
writeFileSync(resolve(home,'config.toml'),config);
const env=Object.fromEntries(Object.entries(process.env).filter(([k])=>/^(path|systemroot|windir|temp|tmp|userprofile|comspec)$/i.test(k)));env.CODEX_HOME=home;
const exe='C:/Users/saedg/.bun/bin/codex.exe';
const rpc=spawn(exe,['app-server','--listen','stdio://'],{cwd:project,env,windowsHide:true,stdio:['pipe','pipe','pipe']});
let seq=0;const pending=new Map();let errors='';rpc.stderr.on('data',x=>errors+=x);
createInterface({input:rpc.stdout}).on('line',line=>{const m=JSON.parse(line);if(pending.has(m.id)){pending.get(m.id)(m);pending.delete(m.id);}});
const send=(method,params)=>new Promise(r=>{const id=++seq;pending.set(id,r);rpc.stdin.write(JSON.stringify({id,method,params})+'\n');});
await send('initialize',{clientInfo:{name:'fixture_capture',version:'0.0.0'},capabilities:{experimentalApi:true}});rpc.stdin.write('{"method":"initialized","params":{}}\n');
const listed=await send('hooks/list',{cwds:[project]});writeFileSync(resolve(base,'hooks-list.json'),JSON.stringify(listed,null,2));
const collect=value=>{if(value&&typeof value==='object'){if(value.key&&value.currentHash)config+=`\n[hooks.state.${JSON.stringify(value.key)}]\nenabled = true\ntrusted_hash = ${JSON.stringify(value.currentHash)}\n`;for(const child of Object.values(value))collect(child);}};
collect(listed);writeFileSync(resolve(home,'config.toml'),config);rpc.stdin.end();await new Promise(r=>rpc.on('exit',r));
const child=spawn(exe,['--no-alt-screen','-a','never','-s','workspace-write','-C',project,'Exercise the native tool once in this fixture directory.'],{cwd:project,env,windowsHide:true,stdio:'inherit'});
const check=setInterval(()=>{if(existsSync(raw)&&readFileSync(raw,'utf8').includes('PostToolUse'))child.kill();},500);
const timer=setTimeout(()=>child.kill(),45000);
const code=await new Promise(r=>child.on('exit',r));clearTimeout(timer);clearInterval(check);server.close();
writeFileSync(resolve(base,'summary.json'),JSON.stringify({code,turns,captured:existsSync(raw),files:existsSync(resolve(project,'capture.txt'))}));
console.log({code,turns,captured:existsSync(raw)?readFileSync(raw,'utf8'):'none'});
